#include <bits/stdc++.h>

using namespace std;

int solve(int n, string s) {
    vector<int> mx(2), cnt(2);
    for (int l = 0; l < n;) {
        int r = l + 1;
        while (r < n and s[l] == s[r]) ++r;
        int c = s[l] - '0';
        int len = r - l;
        mx[c] = max(mx[c], len);
        cnt[c] += len;
        l = r;
    }
    int ans = 2 * n;
    for (int i = 0; i < 2; i++) {
        ans = min(ans, (cnt[i] - mx[i]) * 2 + cnt[i ^ 1]);
    }
    return ans;
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        int n;
        string s;
        cin >> n >> s;
        cout << solve(n, s) << '\n';
    }
}
